// Simple CSV parsing: three comma-separated columns, optional header row.
// Quoted fields containing commas are not supported.
function parseCsv(text: string): Parsed {
  if (!text.trim()) return { error: 'the CSV is empty — paste rows like Centro,2024-01,1250' };
  const lines = text.replace(/^\\uFEFF/, '').split(/\\r?\\n/);
  const rows: Sample[] = [];
  const seen = new Set<string>();
  let start = 0;
  const first = (lines[0] || '').toLowerCase();
  if (first.includes('district') && first.includes('month')) start = 1; // optional header
  for (let i = start; i < lines.length; i++) {
    const raw = lines[i].trim();
    if (!raw) continue;
    const cols = raw.split(',').map(c => c.trim().replace(/^"(.*)"$/, '$1'));
    if (cols.length !== 3) return { error: 'line ' + (i + 1) + ': expected 3 columns (district, month, median_rent), found ' + cols.length };
    const [district, month, rent] = cols;
    if (!district) return { error: 'line ' + (i + 1) + ': the district is empty' };
    if (!MONTH_RE.test(month)) return { error: 'line ' + (i + 1) + ': month "' + month + '" is not in YYYY-MM form (like 2024-01)' };
    const value = Number(rent);
    if (rent === '' || !Number.isFinite(value)) return { error: 'line ' + (i + 1) + ': median_rent "' + rent + '" is not a number' };
    const key = district + '|' + month;
    if (seen.has(key)) return { error: 'line ' + (i + 1) + ': duplicate row for ' + district + ', ' + month };
    seen.add(key);
    rows.push({ district, month, median_rent: value });
  }
  if (rows.length === 0) return { error: 'no data rows found — paste rows like Centro,2024-01,1250' };
  return { rows };
}

