}

// Plot numbers: keep the digits, drop the decorations ("Plot 18" -> "18",
// "#3" -> "3"). The number itself is never touched, and a plot with no
// digits in it at all is left alone rather than guessed at.
function plainPlot(p) {
  const s = String(p == null ? '' : p).trim();
  const digits = s.match(/\\d+/);
