// --- actor.js: waitlist helpers + actions ---
const helper = `// ---- the plot waitlist ----
// One doc per person waiting, in the order they were added (addedAt).
// status: 'waiting' -> 'offered' (with the plot and the date of the offer)
// -> 'joined'. The offer date is recorded so a future "offers expire" rule
// can read it without any change to the data; and when a plot is freed,
// the first person *still waiting* gets it — someone sitting on an offer
// never blocks the rest of the queue.
function waitlistRows() {
  return db.collection('waitlist').get().docs
    .map((d) => ({ id: d.id, body: d.data() }))
    .sort((a, b) => ((a.body.addedAt || '') < (b.body.addedAt || '') ? -1 : (a.body.addedAt || '') > (b.body.addedAt || '') ? 1 : 0));
}

defineActor({`
await files.replace('actor.js', 'defineActor({', helper);

const removeLine = "    remove: { requires: 'interact', run(ctx, a) { db.doc('members/' + a.id).delete(); return 'ok'; } },\n  },\n});"
const newActions = `    remove: { requires: 'interact', run(ctx, a) { db.doc('members/' + a.id).delete(); return 'ok'; } },
    // The plot waitlist, first come (earliest addedAt) first served.
    'waitlistList': { requires: 'view', run() { return waitlistRows(); } },
    'waitlistAdd': { requires: 'interact', run(ctx, a) {
      const name = String((a && a.name) || '').trim();
      if (!name) throw new Error('Type a name — someone has to be on the list.');
      const email = String((a && a.email) || '').trim();
      db.doc('waitlist/w' + Date.now() + '-' + Math.random().toString(36).slice(2, 6)).set({
        name: name, email: email, addedAt: new Date().toISOString(), status: 'waiting',
      });
      return 'ok';
    } },
    // Freeing a plot: the gardener stays on the roster, marked left, with
    // their payment history untouched — the count and the rows never lose
    // anyone. The plot is offered to the first person still waiting.
    'freePlot': { requires: 'interact', run(ctx, a) {
      const doc = db.collection('members').get().docs.find((d) => d.id === (a && a.memberId));
      if (!doc) throw new Error('That member is not on the list.');
      const body = doc.data();
      if (body.left) throw new Error(body.name + ' has already left.');
      const plot = plainPlot(body.plot);
      db.doc('members/' + doc.id).set(Object.assign({}, body, { left: true, leftPlot: plot, plot: '' }));
      const waiting = waitlistRows().filter((w) => w.body.status === 'waiting');
      if (!waiting.length) return { offered: null, plot: plot };
      const first = waiting[0];
      db.doc('waitlist/' + first.id).set(Object.assign({}, first.body, { status: 'offered', plot: plot, offeredAt: new Date().toISOString() }));
      return { offered: first.body.name, plot: plot };
    } },
    // The offer was accepted: the person joins the members list on that
    // plot, with an empty payment record (they have paid nothing yet).
    'acceptOffer': { requires: 'interact', run(ctx, a) {
      const doc = db.collection('waitlist').get().docs.find((d) => d.id === (a && a.waitlistId));
      if (!doc) throw new Error('That waitlist entry is gone.');
      const body = doc.data();
      if (body.status !== 'offered') throw new Error(body.name + ' has not been offered a plot.');
      db.doc('members/m' + Date.now()).set({ name: body.name, email: body.email || '', plot: plainPlot(body.plot), paid: {} });
      db.doc('waitlist/' + doc.id).set(Object.assign({}, body, { status: 'joined', joinedAt: new Date().toISOString() }));
      return 'ok';
    } },
  },
});`
