// and actor.ts (the server) both import from this file.

// The board's columns, in display order.
export const COLUMNS = ['todo', 'doing', 'done'] as const

// A column's id: one of COLUMNS.
export type ColumnId = (typeof COLUMNS)[number]

// A card, as the actor stores and returns it and the page renders it.
// version is optimistic locking: every move bumps it, and a move only
// applies when the caller's expectVersion matches the row's version.
// movedBy / movedAt are set by the actor on every move; null until a
// card has been moved.
export interface Card {
  id: number
  title: string
  owner: string
  column: ColumnId
  version: number
  movedBy: string | null
  movedAt: number | null
}

// A live-update message. After every change the actor publishes one of
// these on the 'cards' room topic and the server pushes it to every open
// page, which re-lists the cards. A discriminated union on 'type';
// parseBoardEvent narrows the raw room payload (which arrives as
// unknown) to it.
export type BoardEvent =
  | { type: 'moved'; id: number; column: ColumnId; by: string }
  | { type: 'added'; id: number; title: string; by: string }

// The room delivers payloads as plain JSON, untyped: check one before
// trusting it, and ignore anything that is not a well-formed BoardEvent.
export function parseBoardEvent(raw: unknown): BoardEvent | null {
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return null
  const o = raw as Record<string, unknown>
  const by = o['by']
  const id = o['id']
  if (typeof by !== 'string' || typeof id !== 'number') return null
  if (o['type'] === 'moved') {
    const column = o['column']
    if (typeof column === 'string' && (COLUMNS as readonly string[]).includes(column)) {
      return { type: 'moved', id, by, column: column as ColumnId }
    }
    return null
  }
  if (o['type'] === 'added') {
    const title = o['title']
    if (typeof title === 'string') return { type: 'added', id, by, title }
    return null
  }
  return null
}
`

