// 1) Migration
await files.write('sql/004_assignees.sql', `-- Card assignees, and the roster of people allowed as assignees.
-- assignee is NULL until a card is assigned (and again after clearing).
-- visitors remembers everyone who has opened the board: the list action
-- stamps the caller into it (name + first/last seen), and assign refuses
-- any name it has never recorded — the only assignable people are the
-- people who actually opened the board.
ALTER TABLE cards ADD COLUMN assignee TEXT;
CREATE TABLE visitors (
  name TEXT PRIMARY KEY,
  first_seen INTEGER NOT NULL,
  last_seen INTEGER NOT NULL
);
`)

// 2) types.ts — Card gains assignee; BoardEvent gains 'assigned' and 'visited'
await files.write('types.ts', `// The shared shapes of the kanban board, defined once: main.ts (the page)
// and actor.ts (the server) both import from this file.

// The board's columns, in display order.
export const COLUMNS = ['todo', 'doing', 'done'] as const

// A column's id: one of COLUMNS.
export type ColumnId = (typeof COLUMNS)[number]

// A card, as the actor stores and returns it and the page renders it.
// version is optimistic locking: every move bumps it, and a move only
// applies when the caller's expectVersion matches the row's version.
// movedBy / movedAt are set by the actor on every move; null until a
// card has been moved. assignee is who the card is assigned to, from the
// visitors table; null means unassigned. It is set by assign, not move,
// so it takes no part in the move race.
export interface Card {
  id: number
  title: string
  owner: string
  column: ColumnId
  version: number
  movedBy: string | null
  movedAt: number | null
  assignee: string | null
}

// A live-update message. After every change the actor publishes one of
// these on the 'cards' room topic and the server pushes it to every open
// page, which re-lists the cards. A discriminated union on 'type';
// parseBoardEvent narrows the raw room payload (which arrives as
// unknown) to it.
// In every variant \`by\` is the name of the visitor who did it — never the
// card's owner. 'visited' has no id: it announces that someone opened the
// board for the first time, so every assign menu gains their name.
export type BoardEvent =
  | { type: 'moved'; id: number; column: ColumnId; by: string }
  | { type: 'added'; id: number; title: string; by: string }
  | { type: 'assigned'; id: number; assignee: string | null; by: string }
  | { type: 'visited'; by: string }

// The room delivers payloads as plain JSON, untyped: check one before
// trusting it, and ignore anything that is not a well-formed BoardEvent.
export function parseBoardEvent(raw: unknown): BoardEvent | null {
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return null
  const o = raw as Record<string, unknown>
  const by = o['by']
  if (typeof by !== 'string') return null
  const type = o['type']
  if (type === 'visited') return { type: 'visited', by }
  const id = o['id']
  if (typeof id !== 'number') return null
  if (type === 'moved') {
    const column = o['column']
    if (typeof column === 'string' && (COLUMNS as readonly string[]).includes(column)) {
      return { type: 'moved', id, by, column: column as ColumnId }
    }
    return null
  }
  if (type === 'added') {
    const title = o['title']
    if (typeof title === 'string') return { type: 'added', id, by, title }
    return null
  }
  if (type === 'assigned') {
    const assignee = o['assignee']
    if (typeof assignee === 'string' || assignee === null) {
      return { type: 'assigned', id, by, assignee }
    }
    return null
  }
  return null
}

// The room delivers each push wrapped in an envelope:
// { topic: 'cards', data: <BoardEvent>, isMe: boolean, peer, ... } —
// narrowed once, here, so the page never touches an unknown.
// isMe says whether *this connection* emitted the event — but for an actor
// push the emitter is the actor, not a tab, so isMe is false even in the
// window that made the change. It is kept for information only; the page
// decides whose change it is by comparing the mover's name.
export interface BoardEnvelope {
  event: BoardEvent
  isMe: boolean
}

export function parseBoardEnvelope(raw: unknown): BoardEnvelope | null {
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return null
  const o = raw as Record<string, unknown>
  const event = parseBoardEvent(o['data'])
  if (event === null) return null
  return { event, isMe: o['isMe'] === true }
}
`)

