const MAIN = `// main.ts - page logic, moved from the inline <script> that was in index.html.
// TypeScript conversion: typed client for slop.actions, no behaviour changes.
// Loaded by index.html via <script type="module" src="main.ts"></script>.

// ---- typed client for the actor (shapes mirror actor.ts's schemas) ----

// tbl_inv columns, matching actor.ts's Item (sql/001_init.sql + sql/002_loc.sql)
interface Item {
  ID: number;
  Nm: string | null;
  Qty: string | null;
  Prc: string | null;
  upd: string | null;
  loc: string | null;
}

// action argument shapes, matching the args schemas declared in actor.ts
interface SaveArgs { nm: string; qty: string; prc: string; id?: number }
interface DelArgs { id: number }

interface SlopActions {
  getAll(a: Record<string, never>): Promise<Item[]>;
  save(a: SaveArgs): Promise<string>;
  del(a: DelArgs): Promise<string>;
  doStuff(a?: Record<string, never>): Promise<Item[]>;
}

interface Slop { actions: SlopActions }

declare global {
  interface Window {
    claude: { use(name: 'slop'): Promise<Slop> };
    // index.html's inline onclick attributes (addItem/edit/del) resolve in
    // global scope; a module's functions are not global, so expose them.
    addItem: () => void;
    edit: (id: number) => void;
    del: (id: number) => void;
  }
}

export {};

let slop: Slop | null = null;
let items: Item[] = [];
let editing: number | null = null;

function needSlop(): Slop {
  if (slop === null) throw new Error('slop client not ready yet');
  return slop;
}

window.claude.use('slop').then(function (s: Slop) { slop = s; load(); });

function load(): void {
  needSlop().actions.getAll({}).then(function (r) { items = r; draw(); });
}

function esc(s: string | null): string {
  const map: Record<string, string> = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
    return map[c];
  });
}

function draw(): void {
  let h = '<tr><th>Name</th><th>Qty</th><th>Price</th><th>Updated</th><th></th></tr>';
  // was \`var total = 0\`: the number 0 only ever stringifies to '0' at the
  // first concatenation, so starting from '0' keeps the rendered total
  // byte-identical (the $0179.88... string-concatenation quirk stays as is).
  let total = '0';
  for (let i = 0; i < items.length; i++) {
    const it = items[i];
