    const line = (Number(it.Qty) * Number(it.Prc)).toFixed(2); // 2 decimals for money
    total = total + line;
  }
  boxById('tbl').innerHTML = h;
  boxById('tot').innerHTML = 'Total stock value: $' + total;
}

